187:     g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(0.22,t+0.2);g.gain.linearRampToValueAtTime(0,t+1.3);q.start(t);q.stop(t+1.35);}
188:   else if(kind==='boom'){const s=a.createBufferSource();s.buffer=noiseBuf();const f=a.createBiquadFilter();f.type='lowpass';
