import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
page.on('pageerror', e => console.error('PAGEERROR', e.message));
await page.goto('http://127.0.0.1:8765/index.html', { waitUntil: 'load' });
await page.waitForTimeout(1000);
const data = await page.evaluate(() => {
  startGame(0);
  return { state: game.state, player: {x:player.x,y:player.y,a:player.a}, windows: game.map.winW.map(w=>({x:w.x,y:w.y,wx:w.wx,wy:w.wy,dx:w.dx,dy:w.dy,boards:w.boards})) };
});
console.log(JSON.stringify(data));
await page.screenshot({path:'/tmp/opencode/zombies-play-test.jpg',type:'jpeg',quality:75});
await browser.close();

