function makeWallTex(base,size){
  size=size||128;const c=mkCanvas(size,size),x=c.getContext('2d');
  x.fillStyle='#17191a';x.fillRect(0,0,size,size);
  const blockW=32,blockH=16;
  for(let row=0;row<size/blockH;row++)for(let col=-1;col<size/blockW+1;col++){
    const bx=col*blockW+(row%2)*blockW/2,by=row*blockH;
    const shade=0.82+Math.random()*0.34;
    x.fillStyle=base;x.fillRect(bx+1,by+1,blockW-2,blockH-2);
    x.fillStyle=`rgba(255,224,184,${0.035+Math.random()*0.055})`;x.fillRect(bx+2,by+2,blockW-4,2);
    x.fillStyle=`rgba(0,0,0,${0.10+Math.random()*0.10})`;x.fillRect(bx+2,by+blockH-3,blockW-4,2);
    x.fillStyle=`rgba(0,0,0,${0.07+Math.random()*0.06})`;x.fillRect(bx+blockW-3,by+2,2,blockH-4);
    x.fillStyle=`rgba(255,255,255,${(shade-0.8)*0.13})`;x.fillRect(bx+3,by+4,blockW-8,1);
  }
  // Damp streaks, chipped plaster, and fine grit break up the repeating masonry.
  for(let i=0;i<18;i++){
    const sx=Math.random()*size,sy=Math.random()*size,len=5+Math.random()*30;
    x.strokeStyle=`rgba(8,9,10,${0.08+Math.random()*0.16})`;x.lineWidth=0.5+Math.random()*1.5;
    x.beginPath();x.moveTo(sx,sy);x.lineTo(sx+(Math.random()-.5)*5,sy+len);x.stroke();
  }
  for(let i=0;i<520;i++){
    const light=Math.random()<0.27,alpha=Math.random()*(light?0.10:0.16);
    x.fillStyle=light?`rgba(220,210,190,${alpha})`:`rgba(0,0,0,${alpha})`;
    x.fillRect((Math.random()*size)|0,(Math.random()*size)|0,1+Math.random()*2,1+Math.random()*2);
  }
  const edge=x.createLinearGradient(0,0,size,0);edge.addColorStop(0,'rgba(0,0,0,.24)');edge.addColorStop(.12,'rgba(0,0,0,0)');edge.addColorStop(.84,'rgba(0,0,0,0)');edge.addColorStop(1,'rgba(0,0,0,.18)');
  x.fillStyle=edge;x.fillRect(0,0,size,size);
  return c;
}

